import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Köşe yuvarlama, keskin köşeleri yumuşatır. Görsel modern görünür ve arayüzde doğal durur.</p>\n<p>Doğru yarıçap, görseli yüceltir. Yanlış yarıçap ise görseli bozar ya da fark edilmez.</p>\n<p>Bu kılavuz, yarıçapın ne olduğunu, köşe başına kontrolü ve daire ile hap biçimlerini anlatıyor.</p>\n<h2 id=\"what-rounding-does\">Köşe yuvarlama gerçekte ne yapar?</h2>\n<p>Köşe yuvarlama, görselin dört köşesini keser. Kesilen alan saydam ya da düz renkle dolar.</p>\n<p>Yuvarlama, görselin biçimini değiştirir. Kare fotoğraf, yuvarlak köşeli karta döner.</p>\n<p>Yuvarlama, kalite kaybettirmez. Kalan pikseller orijinal kalitededir.</p>\n<h2 id=\"radius-explained\">Köşe yarıçapı, açıklanıyor</h2>\n<p>Yarıçap, köşenin ne kadar yuvarlak olduğunu belirler. Küçük yarıçap hafif, büyük yarıçap belirgin yuvarlama yapar.</p>\n<p>Yarıçap piksel ya da yüzde olarak ayarlanır. Yüzde, fotoğraf boyutuna göre ölçeklenir.</p>\n<p>Yüzde 50 yarıçap, kareyi daireye çevirir. Bu, avatarlar için kullanılan kısayoldur.</p>\n<h2 id=\"per-corner-control\">Köşe başına kontrol: bir köşeyi tek tek yuvarlamak</h2>\n<p>Köşe başına kontrol, her köşeyi ayrı ayarlar. Yalnızca üst köşeleri yuvarlayabilirsiniz.</p>\n<p>Bu kontrol, kart tasarımlarında kullanılır. Kartın üstü yuvarlak, altı keskin olabilir.</p>\n<p>Her köşeye ayrı yarıçap vermek yavaştır; yaygın kullanımda dört köşe eşit yuvarlanır.</p>\n<h2 id=\"full-circle-pill\">Tam daire ve hap biçimi</h2>\n<p>Tam daire, karenin yüzde 50 yarıçapla yuvarlanmasıdır. Avatarlar için idealdir.</p>\n<p>Hap biçimi, dikdörtgenin kısa kenarına göre yuvarlanmasıdır. Düğme ve etiketlerde kullanılır.</p>\n<p>Hap biçimi, geniş görsellerde zarif görünür. Afiş ve kapaklarda kullanılır.</p>\n<h2 id=\"transparent-vs-solid-fill\">Köşelerde saydam ya da düz dolgu</h2>\n<p>Saydam dolguda köşeler tamamen kaybolur; görsel her arka planın üstünde pürüzsüz görünür.</p>\n<p>Düz dolguda köşeler tek renkle kapanır; beyaz dolgu, beyaz zemin üstünde görünmez olur.</p>\n<p>Saydam dolgu için PNG kullanın. JPG saydamlığı desteklemez; köşeler beyaz dolar.</p>\n<h2 id=\"formats-png-webp-jpg\">Formatlar: PNG, WebP ve JPG</h2>\n<p>PNG saydamlığı destekler; yuvarlak köşeler için idealdir. Köşeler her zeminde temiz görünür.</p>\n<p>WebP de saydamlığı destekler ve daha küçüktür. Web için WebP kullanın.</p>\n<p>JPG saydamlığı desteklemez. Yuvarlak köşeler JPG'de beyaz dolar; bu bazen kabul edilebilir.</p>\n<h2 id=\"rounding-for-avatars\">Avatar ve profil fotoğrafları için köşe yuvarlama</h2>\n<p>Avatarlarda daire biçimi standarttır; kare fotoğrafı yüzde 50 yarıçapla çevirdiğinizde tam daire elde edersiniz.</p>\n<p>Yüzü merkeze alın. Daire, köşeleri keser; yüz çerçevenin dışında kalmamalıdır.</p>\n<p>Köşe yuvarlamada kaynak çözünürlüğü önemlidir; küçük fotoğraftan üretilen avatar, dairede bulanık görünür.</p>\n<h2 id=\"rounding-for-cards\">Kart ve arayüz grafikleri için köşe yuvarlama</h2>\n<p>Kartlar, hafif yuvarlak köşe ister. Yüzde 5-10 yarıçap, modern görünür.</p>\n<p>Tüm kartlarda aynı yarıçapı kullanın. Tutarlılık, arayüzü profesyonel gösterir.</p>\n<p>Yarıçapta aşırıya kaçmayın; fazla yuvarlak kartlar, görseli acemi işi gibi gösterir.</p>\n<h2 id=\"smooth-edges\">Eğri kenarlar neden pürüzsüz görünür?</h2>\n<p>Kenar yumuşatma, eğriyi pürüzsüz gösterir. Pikseller, kenar boyunca karıştırılır.</p>\n<p>Yumuşatma olmadan kenarlar dişli görünür. Modern araçlar yumuşatmayı otomatik yapar.</p>\n<p>Küçük görsellerde yumuşatma daha önemlidir. Düşük çözünürlükte dişli kenar belirgindir.</p>\n<h2 id=\"rounding-and-print\">Baskı için köşe yuvarlama</h2>\n<p>Baskıda yuvarlak köşe, kesim gerektirir. Baskı merkezi, köşeleri kesmelidir.</p>\n<p>Baskıdan önce merkeze sorun. Yuvarlak köşe baskısı, ek ücret gerektirebilir.</p>\n<p>Etiket ve çıkartmalarda yuvarlak köşe yaygındır. Kesim çizgisini belirtin.</p>\n<h2 id=\"rounding-vs-cropping\">Yuvarlamak mı kırpmak mı: farklı işler</h2>\n<p>Yuvarlama biçimi değiştirir; kırpma alanı değiştirir. İki işlem farklıdır.</p>\n<p>Önce kırpın, sonra yuvarlayın. Sıralama, gereksiz işi önler.</p>\n<p>İkisi birlikte de yapılabilir. Önce hedef biçime kırpın, sonra köşeleri yuvarlayın.</p>\n<h2 id=\"rounding-and-borders\">Köşe yuvarlama ve çerçeve eklemek</h2>\n<p>Yuvarlak köşe ile çerçeve bir arada kullanılır; çerçeve, köşenin yuvarlaklığını aynen izler.</p>\n<p>Çerçeve ve fotoğraf yarıçapını birlikte ayarlayın. Dış ve iç yarıçap uyumlu olmalı.</p>\n<p>Yuvarlak köşede çerçeve ince olmalı; kalın çerçeve, köşenin yumuşak görünümünü ezer.</p>\n<h2 id=\"rounding-on-mobile\">Telefon ve tablette köşe yuvarlamak</h2>\n<p>Araç, telefon tarayıcısında da çalışır; fotoğrafı yükleyip yarıçapı ayarlamanız yeterlidir.</p>\n<p>Küçük ekranlarda hassas yarıçap tutturmak güçtür; milimetrik ayar için bilgisayar daha rahattır.</p>\n<p>Dosyalar İndirilenler klasörüne iner. Bulamazsanız tarayıcının indirme geçmişini kontrol edin.</p>\n<h2 id=\"privacy-local-processing\">Gizlilik: hiçbir şey yüklemeden yuvarlamak</h2>\n<p>Yuvarlama aracı tamamen tarayıcıda çalışır. Fotoğraflarınız sunucuya yüklenmez.</p>\n<p>Bu güvence, özel fotoğraflarda önemlidir. Aile ve müşteri görsellerini endişesiz yuvarlayabilirsiniz.</p>\n<p>İş bitince tarayıcı verisi temizlenir. Görselleriniz cihazınızdan ayrılmaz.</p>\n<h2 id=\"common-rounding-mistakes\">Köşe yuvarlarken yaygın hatalar</h2>\n<p>En yaygın hata, JPG kullanmaktır. JPG saydamlığı desteklemez; köşeler beyaz dolar.</p>\n<p>Bir başka hata, çok büyük yarıçaptır. Aşırı yuvarlama, fotoğrafı daireye çevirir.</p>\n<p>Üçüncü hata, tutarsızlıktır. Her kartta farklı yarıçap, arayüzü dağınık gösterir.</p>\n<h2 id=\"rounding-workflow\">Yuvarlamayı temiz tutan bir akış</h2>\n<p>Önce biçimi belirleyin. Daire mi, hap mı, hafif yuvarlak mı?</p>\n<p>Sonra yarıçapı ayarlayın. Önizlemede sonucu kontrol edin.</p>\n<p>Son olarak formatı seçin. Saydamlık için PNG kullanın.</p>\n<h2 id=\"rounding-for-stickers\">Çıkartma ve etiketler için köşe yuvarlama</h2>\n<p>Çıkartmalar yuvarlak köşe ister. Keskin köşe, çıkartmada kalkar.</p>\n<p>Etiketlerde hafif yuvarlama kullanın. Yüzde 10-15 yarıçap yeterlidir.</p>\n<p>Baskıdan önce kesim çizgisini belirtin. Baskı merkezi, köşeleri kesmelidir.</p>\n<p>Özetle: yarıçapı hedefe göre seçin, saydamlık için PNG kullanın. Adımlar için <a href=\"/tr/blog/gorsel-koseleri-nasil-yuvarlatilir\">Görsel köşeleri nasıl yuvarlanır</a> yazısına bakın; karşılaştırma için <a href=\"/tr/blog/yuvarlatilmis-koseler-vs-daire-kirpma\">yuvarlak köşeler ve daire kırpma karşılaştırması</a> yardımcı olur. Çerçeve için <a href=\"/tr/gorsel-cerceve-olusturucu\">görsel çerçeve oluşturucu</a> hazırdır; araç ise <a href=\"/tr/gorsel-kose-yuvarla\">köşe yuvarlama</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Yuvarlak köşelerim neden saydamlık yerine beyaz arka plan gösteriyor?","answer":"Çünkü dosyayı JPG olarak indirdiniz; JPG saydamlığı desteklemez ve köşeler beyaz dolar. Saydam köşeler için PNG ya da WebP olarak indirin. Önizlemede saydam alanlar damalı desenle görünür."},{"question":"Fotoğrafımdan nasıl mükemmel bir daire yaparım?","answer":"Kare fotoğraf kullanın ve yarıçapı yüzde 50 olarak ayarlayın. Yüzü merkeze alın; daire köşeleri keser. Yüksek çözünürlüklü kaynak kullanın; küçük kaynaktan üretilen avatar bulanık görünür."},{"question":"Yalnızca iki üst köşeyi yuvarlayabilir miyim?","answer":"Evet. Köşe başına kontrol modunu kullanın; her köşeyi ayrı ayarlayabilirsiniz. Üst köşelere yarıçap verin, alt köşeleri sıfırda bırakın. Bu, kart tasarımlarında yaygındır."},{"question":"Profil fotoğrafı için hangi yarıçapı kullanmalıyım?","answer":"Daire avatar için yüzde 50, yuvarlak kare için yüzde 10-20 kullanın. Platform daire gösteriyorsa yüzde 50 gerekir. Yüzü merkeze alın; daire köşeleri keser."},{"question":"Köşeleri yuvarlamak görsel kalitesini düşürür mü?","answer":"Hayır. Yuvarlama kalite kaybettirmez; kalan pikseller orijinal kalitededir. Yalnızca köşeler atılır. Küçük görsellerde kenar yumuşatma önemlidir; modern araçlar bunu otomatik yapar."},{"question":"Ekran görüntüsünün köşelerini yuvarlayabilir miyim?","answer":"Evet. Ekran görüntüsünü yükleyin ve yarıçapı ayarlayın; hafif yuvarlama modern görünür. Saydam köşeler için PNG olarak indirin. Ekran görüntüleri için yüzde 5-10 yarıçap yeterlidir."}];
